import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ShinyTextProps = Record<string, any>;

const ShinyText: React.FC<ShinyTextProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  text = "Shiny Text Animation",
  fontSize = 100,
  fontWeight = "700",
  letterSpacing = 0,
  speed = 2,
  delay = 1,
  yoyo = false,
  color = "#4a4a4a",
  shineColor = "#ffffff",
  spread = 120,
  reverseDirection = false,
}) => {
  useFontLoader(["Inter", "Poppins", "Roboto"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color & Background Logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Time calculations
  const cycleDurationFrames = speed * fps;
  const delayFrames = delay * fps;
  
  // Determine progress (0 to 1) based on loop logic
  let progress = 0;

  if (yoyo) {
    // Yoyo Cycle: Forward -> Delay -> Backward -> Delay
    const totalCycleFrames = (cycleDurationFrames + delayFrames) * 2;
    const currentFrameInCycle = frame % totalCycleFrames;

    if (currentFrameInCycle < cycleDurationFrames) {
      // Forward Phase
      progress = interpolate(currentFrameInCycle, [0, cycleDurationFrames], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    } else if (currentFrameInCycle < cycleDurationFrames + delayFrames) {
      // Delay Phase (Hold at end)
      progress = 1;
    } else if (currentFrameInCycle < (cycleDurationFrames * 2) + delayFrames) {
      // Backward Phase
      const reverseStart = cycleDurationFrames + delayFrames;
      progress = interpolate(
        currentFrameInCycle, 
        [reverseStart, reverseStart + cycleDurationFrames], 
        [1, 0],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );
    } else {
      // Delay Phase (Hold at start)
      progress = 0;
    }
  } else {
    // Standard Loop: Forward -> Delay -> Reset
    const totalCycleFrames = cycleDurationFrames + delayFrames;
    const currentFrameInCycle = frame % totalCycleFrames;

    if (currentFrameInCycle < cycleDurationFrames) {
      progress = interpolate(currentFrameInCycle, [0, cycleDurationFrames], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    } else {
      progress = 1; // Hold at end (off-screen)
    }
  }

  // Map progress to background position percentages
  // Logic from source: 0 -> 150%, 1 -> -50% (moves Right to Left visually if angle is standard)
  // If reverseDirection is true, we swap the inputs.
  
  const startPos = reverseDirection ? -50 : 150;
  const endPos = reverseDirection ? 150 : -50;

  const bgPositionValue = interpolate(progress, [0, 1], [startPos, endPos]);
  const backgroundPosition = `${bgPositionValue}% center`;

  // Gradient Construction
  // Source: linear-gradient(${spread}deg, ${color} 0%, ${color} 35%, ${shineColor} 50%, ${color} 65%, ${color} 100%)
  const gradient = `linear-gradient(${spread}deg, ${color} 0%, ${color} 35%, ${shineColor} 50%, ${color} 65%, ${color} 100%)`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      <span
        style={{
          fontSize: fontSize,
          fontWeight: fontWeight as any,
          letterSpacing: `${letterSpacing}px`,
          backgroundImage: gradient,
          backgroundSize: "200% auto",
          backgroundPosition: backgroundPosition,
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          WebkitTextFillColor: "transparent",
          color: "transparent", // Fallback
          display: "inline-block",
          textAlign: "center",
          whiteSpace: "nowrap",
          // Ensure hardware acceleration for smooth gradients
          willChange: "background-position", 
        }}
      >
        {text}
      </span>
    </AbsoluteFill>
  );
};

export default ShinyText;